// MAISON ÉLAN — build-time database provisioning for deployed environments (v2).
// Runs inside `vercel-build` (and `build`) BEFORE `next build`, after the Prisma
// Client has been generated by scripts/prisma-generate.cjs.
//
// ─── Why v2? ──────────────────────────────────────────────────────────────────
// v1 used `prisma db push` + a seed that could fail or skip SILENTLY (warn +
// exit 0). Real-world result: a "successful" deploy with an empty database and
// a webmaster dashboard that just says "Something went wrong. Please try
// again." v2 makes provisioning deterministic and LOUD:
//
//   Step 1  prisma migrate deploy
//           • fresh empty database      → applies prisma/migrations/0_init
//           • database already has tables but NO migration history (e.g. it
//             was created by `db push` or an external tool) → the deploy fails
//             with P3005 (“database schema is not empty”), and the script
//             AUTOMATICALLY BASELINES: `prisma migrate resolve --applied 0_init`
//             → retry. Nothing is dropped, no data is touched.
//           • still failing             → exit 1 (previous deployment stays live)
//   Step 1b drift check (SKIP_DRIFT_CHECK=1 to opt out)
//           • `prisma migrate diff` between the LIVE database and the shipped
//             schema. A baseline only tells Prisma “history starts here” — it
//             cannot prove the existing tables actually MATCH the migration
//             (B-08: a database built from an older schema would otherwise be
//             marked valid and drift silently until a random 500). A non-empty
//             diff is therefore a fatal deploy error with remediation steps.
//           • if the diff tool itself cannot run, the check degrades to a
//             warning (cannot-verify is never treated as verified).
//   Step 2  seed (prisma/seed.ts, ensure-exists semantics)
//           • fills every missing seed row; never deletes; never overwrites
//             admin-owned rows; repairs invalid bcrypt hashes on demo accounts
//           • failure                   → exit 1 unless SKIP_SEED=1
//   Step 3  verify (prisma/seed.ts --verify)
//           • prints per-table row counts as build-log PROOF that the database
//             actually contains data (this is what v1 could not tell you)
//           • users==0 or products==0   → exit 1 unless SKIP_SEED=1
//
// Context rules:
//   - VERCEL=1 or DATABASE_URL starts with postgres… → provision (all 3 steps)
//   - VERCEL=1 and DATABASE_URL missing/SQLite      → FATAL: a Vercel deploy
//     without a usable database URL must never build into a broken site (v1
//     skipped silently here — the root cause of the empty-DB incident).
//   - local machine with SQLite                     → no-op; manage the DB via
//     `bun run db:push` / `bun run db:seed`.
//
// Escape hatch: SKIP_SEED=1 → provision schema only (then bootstrap the owner
// account via /webmaster/setup); verification downgraded to a warning.

/* eslint-disable @typescript-eslint/no-require-imports -- build-time helper: must stay CommonJS, runs under node/bun before any bundling */

const { execSync, execFileSync } = require("child_process");
const fs = require("fs");
const path = require("path");

const root = process.cwd();
const TAG = "[prisma-deploy-db]";

// ── helpers ──────────────────────────────────────────────────────────────────

function databaseUrl() {
  if (process.env.DATABASE_URL) return process.env.DATABASE_URL;
  try {
    const envFile = fs.readFileSync(path.join(root, ".env"), "utf8");
    const m = envFile.match(/^DATABASE_URL\s*=\s*"?([^"\r\n#]+)"?/m);
    return m ? m[1].trim() : "";
  } catch {
    return "";
  }
}

/** Run a command, trying each runner. Returns {ok, status, output}.
 *  A runner is only skipped when it is genuinely missing (exit 127 / ENOENT);
 *  real command failures stop the fallback chain and are reported. */
function runChain(argsList, { timeout = 300000 } = {}) {
  let lastOutput = "";
  let lastStatus = null;
  for (const args of argsList) {
    try {
      const out = execSync(args, {
        cwd: root,
        env: childEnv,
        timeout,
        stdio: ["ignore", "pipe", "pipe"],
        encoding: "utf8",
      });
      lastOutput = String(out ?? "");
      if (lastOutput.trim()) console.log(lastOutput.trimEnd());
      return { ok: true, status: 0, output: lastOutput };
    } catch (err) {
      const e = err || {};
      const status = typeof e.status === "number" ? e.status : null;
      const output = `${e.stdout ?? ""}${e.stderr ?? ""}`;
      lastOutput = output;
      lastStatus = status;
      const missing =
        e.code === "ENOENT" ||
        status === 127 ||
        /command not found|not found:/i.test(output) ||
        /ENOENT/i.test(e.message ?? "");
      if (missing) {
        console.log(`${TAG} runner not available (${args.split(" ")[0]}…) — trying next.`);
        continue;
      }
      // real failure: report and stop
      if (output.trim()) console.error(output.trimEnd());
      return { ok: false, status, output };
    }
  }
  return { ok: false, status: lastStatus, output: lastOutput || "no runner available" };
}

/** Run a command with array args (no shell → safe for URLs with special chars).
 *  Tries each [cmd, …args] pair; only genuinely-missing runners are skipped. */
function runFileChain(argsList, { timeout = 300000 } = {}) {
  let lastOutput = "";
  let lastStatus = null;
  for (const [cmd, ...args] of argsList) {
    try {
      const out = execFileSync(cmd, args, {
        cwd: root,
        env: childEnv,
        timeout,
        stdio: ["ignore", "pipe", "pipe"],
        encoding: "utf8",
      });
      lastOutput = String(out ?? "");
      if (lastOutput.trim()) console.log(lastOutput.trimEnd());
      return { ok: true, status: 0, output: lastOutput };
    } catch (err) {
      const e = err || {};
      const status = typeof e.status === "number" ? e.status : null;
      const output = `${e.stdout ?? ""}${e.stderr ?? ""}`;
      lastOutput = output;
      lastStatus = status;
      const missing =
        e.code === "ENOENT" ||
        status === 127 ||
        /command not found|not found:/i.test(output) ||
        /ENOENT/i.test(e.message ?? "");
      if (missing) {
        console.log(`${TAG} runner not available (${cmd}) — trying next.`);
        continue;
      }
      if (output.trim()) console.error(output.trimEnd());
      return { ok: false, status, output };
    }
  }
  return { ok: false, status: lastStatus, output: lastOutput || "no runner available" };
}

function fatal(lines) {
  for (const l of lines) console.error(`${TAG} ${l}`);
  console.error(`${TAG} Failing the build so the previous (working) deployment stays live.`);
  process.exit(1);
}

// ── context resolution ───────────────────────────────────────────────────────

const url = databaseUrl();
const vercel = process.env.VERCEL === "1";
const skipSeed = process.env.SKIP_SEED === "1";

if (!url) {
  if (vercel) {
    fatal([
      "DATABASE_URL is NOT set, but this is a Vercel build.",
      "Fix: Vercel Project → Settings → Environment Variables → add DATABASE_URL",
      "(Neon pooled connection string, host contains '-pooler', ending with",
      "?sslmode=require&pgbouncer=true) and DIRECT_DATABASE_URL (Neon direct",
      "string). Then redeploy.",
    ]);
  }
  console.warn(`${TAG} No DATABASE_URL found (env or .env) — local machine, skipping DB provisioning.`);
  process.exit(0);
}

if (!url.startsWith("postgres")) {
  if (vercel) {
    fatal([
      `DATABASE_URL does not look like a PostgreSQL URL (starts with "${url.split(":")[0]}").`,
      "On Vercel there is no persistent SQLite disk. Point DATABASE_URL at your Neon/Postgres",
      "pooled connection string and set DIRECT_DATABASE_URL to the direct one, then redeploy.",
    ]);
  }
  console.log(`${TAG} SQLite context (local/VPS) — nothing to do. Manage the DB with \`bun run db:push\` / \`bun run db:seed\`.`);
  process.exit(0);
}

console.log(`${TAG} PostgreSQL context — target ${url.split("@").pop() || "(set)"}`);

// Neon best practice: schema/migration operations prefer the DIRECT (unpooled)
// string. If DIRECT_DATABASE_URL was not configured we fall back to the pooled
// URL — Neon's pooler accepts DDL, so provisioning still works, but warn.
const childEnv = { ...process.env };
if (!childEnv.DIRECT_DATABASE_URL) {
  childEnv.DIRECT_DATABASE_URL = url;
  console.warn(`${TAG} DIRECT_DATABASE_URL is not set — falling back to DATABASE_URL for migrations.`);
  console.warn(`${TAG} Recommended: add DIRECT_DATABASE_URL (Neon direct string, no '-pooler') for reliable DDL.`);
}

const PG_SCHEMA = "prisma/schema.postgres.prisma";
const BASELINE_MIGRATION = "0_init";

const migrateRunners = [
  `node_modules/.bin/prisma migrate deploy --schema ${PG_SCHEMA}`,
  `npx prisma migrate deploy --schema ${PG_SCHEMA}`,
  `bunx prisma migrate deploy --schema ${PG_SCHEMA}`,
];
const baselineRunners = [
  `node_modules/.bin/prisma migrate resolve --applied ${BASELINE_MIGRATION} --schema ${PG_SCHEMA}`,
  `npx prisma migrate resolve --applied ${BASELINE_MIGRATION} --schema ${PG_SCHEMA}`,
  `bunx prisma migrate resolve --applied ${BASELINE_MIGRATION} --schema ${PG_SCHEMA}`,
];
const seedRunners = [
  "bun prisma/seed.ts",
  "node_modules/.bin/prisma db seed --schema prisma/schema.postgres.prisma",
  "npx --yes tsx prisma/seed.ts",
  "bunx tsx prisma/seed.ts",
];
const verifyRunners = [
  "bun prisma/seed.ts --verify",
  "npx --yes tsx prisma/seed.ts --verify",
  "bunx tsx prisma/seed.ts --verify",
];

function needsBaseline(output) {
  // Deliberately NARROW (B-08): only the official P3005 signature means “tables
  // exist, no migration history”. Broad phrases like “already exists” also
  // match unrelated failures (a half-applied migration, a leftover helper
  // table) — baselining on those would mark a WRONG schema as valid.
  return /P3005|database schema is not empty/i.test(output || "");
}

// ── Step 1/3: schema — prisma migrate deploy (with auto-baseline) ────────────
console.log(`${TAG} Step 1/3 — applying migrations (prisma migrate deploy)…`);
let step1 = runChain(migrateRunners);

if (!step1.ok && needsBaseline(step1.output)) {
  console.log(`${TAG} Database already has tables but no migration history — baselining.`);
  console.log(`${TAG} Marking migration "${BASELINE_MIGRATION}" as applied (no data is changed), then re-deploying…`);
  const resolved = runChain(baselineRunners);
  if (!resolved.ok) {
    fatal([
      `Could not baseline the database (prisma migrate resolve failed, exit ${resolved.status}).`,
      "Manual fix: run `bun run db:baseline` against this database, then redeploy.",
    ]);
  }
  step1 = runChain(migrateRunners);
}

if (!step1.ok) {
  const out = step1.output || "";
  if (/P1012|Environment variable not found/i.test(out)) {
    fatal([
      "Migration failed: a database environment variable is missing or invalid (P1012).",
      "Check DATABASE_URL and DIRECT_DATABASE_URL in your deployment settings, then redeploy.",
    ]);
  }
  if (/P1001|Can't reach database server|ECONNREFUSED|ETIMEDOUT/i.test(out)) {
    fatal([
      "Migration failed: database is unreachable (P1001).",
      "Check that the Neon compute is active and the host/user/password are correct.",
    ]);
  }
  if (/P3018|A migration failed to apply/i.test(out)) {
    fatal([
      "A migration failed to apply (P3018). Inspect the migration output above, fix the",
      "database state, then mark it resolved with `bun run db:migrate:status` / `prisma migrate resolve`.",
    ]);
  }
  fatal([
    `prisma migrate deploy FAILED (exit ${step1.status}).`,
    "If your database was created by `db push` with a DIFFERENT schema, either",
    "  (a) sync it: run `bun run db:push:pg` (accepts data loss), or",
    "  (b) start fresh: drop all tables in the database and redeploy.",
  ]);
}
console.log(`${TAG} Schema is up to date.`);

// ── Step 1b: drift check — prove the live schema MATCHES the shipped schema ──
// A baseline (or a migration) only fixes the migration HISTORY; it cannot prove
// the existing tables equal `0_init`. Compare the live database against the
// schema datamodel: any difference means the store runs on a schema Prisma does
// not expect → fail the deploy instead of shipping silent drift (B-08).
if (process.env.SKIP_DRIFT_CHECK === "1") {
  console.log(`${TAG} Step 1b — SKIP_DRIFT_CHECK=1 → skipping schema drift check.`);
} else {
  console.log(`${TAG} Step 1b — checking live schema against prisma/schema.postgres.prisma…`);
  const diffArgs = [
    ["node_modules/.bin/prisma", "migrate", "diff",
      "--from-url", childEnv.DIRECT_DATABASE_URL,
      "--to-schema-datamodel", PG_SCHEMA, "--script"],
    ["npx", "--yes", "prisma", "migrate", "diff",
      "--from-url", childEnv.DIRECT_DATABASE_URL,
      "--to-schema-datamodel", PG_SCHEMA, "--script"],
    ["bunx", "prisma", "migrate", "diff",
      "--from-url", childEnv.DIRECT_DATABASE_URL,
      "--to-schema-datamodel", PG_SCHEMA, "--script"],
  ];
  const drift = runFileChain(diffArgs);
  if (!drift.ok) {
    // Tool unavailable/failed ≠ verified. Degrade loudly, never block on it.
    console.warn(`${TAG} ⚠ Drift check could not run (exit ${drift.status}). Continuing — but verify the schema manually: bun run db:migrate:status`);
  } else {
    const meaningful = drift.output
      .split("\n")
      .map((l) => l.trim())
      .filter((l) => l && !l.startsWith("--"))
      .join("\n");
    if (meaningful) {
      console.error(`${TAG} Schema drift detected — the live database does NOT match the shipped schema:`);
      console.error(drift.output.trimEnd().split("\n").slice(0, 40).join("\n"));
      fatal([
        "Drift check FAILED: the database schema differs from prisma/schema.postgres.prisma.",
        "A baseline/deploy can never fix tables that were created from a different schema.",
        "Fix options:",
        "  (a) sync the database (accepts data loss): run `bun run db:push:pg` against it, then redeploy;",
        "  (b) start fresh: drop all tables in the database and redeploy;",
        "  (c) escape hatch: SKIP_DRIFT_CHECK=1 (only if you manage the schema out-of-band).",
      ]);
    }
    console.log(`${TAG} Drift check passed — live schema matches the shipped schema.`);
  }
}

// ── Step 2/3: seed (ensure-exists; fatal unless SKIP_SEED=1) ─────────────────
if (skipSeed) {
  console.log(`${TAG} Step 2/3 — SKIP_SEED=1 → skipping seed (bootstrap owner via /webmaster/setup).`);
} else {
  console.log(`${TAG} Step 2/3 — seeding (ensure-exists: fills missing rows, never deletes)…`);
  const seeded = runChain(seedRunners);
  if (!seeded.ok) {
    fatal([
      `Seed FAILED (exit ${seeded.status}).`,
      "The store would go live with an empty catalog — this is treated as a broken deploy.",
      "Check the seed output above. Deliberately skip demo data with SKIP_SEED=1.",
    ]);
  }
}

// ── Step 3/3: verify — proof that the database actually contains data ────────
console.log(`${TAG} Step 3/3 — verifying database contents…`);
if (skipSeed) childEnv.SEED_VERIFY_ALLOW_EMPTY = "1"; // buyer's explicit choice
const verify = runChain(verifyRunners);

if (!verify.ok) {
  if (skipSeed) {
    console.warn(`${TAG} Verification FAILED (continuing because SKIP_SEED=1). Check the output above.`);
  } else {
    fatal([
      `Database verification FAILED (exit ${verify.status}).`,
      "The schema may be applied but empty, or tables may be missing.",
      "Re-run the deploy with SKIP_SEED unset; if tables are missing, run `bun run db:push:pg` or drop the tables and let migrations recreate them.",
    ]);
  }
} else {
  console.log(`${TAG} ✅ Database provisioned and verified. The storefront has data.`);
}
process.exit(0);
